use vstd::prelude::*;

verus! {

fn is_odd_at_index_odd(a: &Vec<i32>) -> (result: bool)
    ensures
        // result holds exactly when every element at an odd index is odd
        result ==
          (forall |i: nat|
             i < a.len() &&
             i % 2 == 1
             ==> ((a@)[i] % 2 != 0))
{
    // We scan the array at odd indices: 1, 3, 5, …
    let mut idx: usize = 1;
    while idx < a.len()
        invariant
            // idx never exceeds the length
            idx <= a.len(),
            // for all odd j < idx, a[j] is already known to be odd
            forall |j: nat|
              j < idx &&
              j % 2 == 1
              ==> ((a@)[j] % 2 != 0),
        decreases
            // the remaining indices to check
            a.len() - idx,
    {
        // if we find an even element at an odd index, we can return false
        if a[idx] % 2 == 0 {
            // witness that the universal property fails at j = idx
            assert(idx < a.len());
            assert(idx % 2 == 1);
            assert(a[idx] % 2 == 0);
            // hence not (forall odd j < len. a[j] is odd)
            assert(!(forall |j: nat|
                       j < a.len() &&
                       j % 2 == 1
                       ==> ((a@)[j] % 2 != 0)));
            return false;
        }
        // otherwise jump to the next odd index
        idx = idx + 2;
    }

    // We've checked all odd indices < a.len() without finding a violation.
    // So the universal property holds.
    assert(idx >= a.len());
    assert(forall |j: nat|
             j < a.len() &&
             j % 2 == 1
             ==> ((a@)[j] % 2 != 0));
    true
}

} // verus!

fn main() {
    // some quick runtime checks
    let v1: Vec<i32> = vec![2, 3, 4, 5, 6];
    assert!(is_odd_at_index_odd(&v1) == true);   // indices 1 and 3 are 3 and 5, both odd

    let v2: Vec<i32> = vec![0, 2, 0, 7];
    assert!(is_odd_at_index_odd(&v2) == false);  // index 1 holds 2, which is even

    let v3: Vec<i32> = Vec::new();
    assert!(is_odd_at_index_odd(&v3) == true);   // empty array vacuously true
}